34. func inspectSingle(path, module string) ([]*ast.AnnotationsRef, error) {
35. 	mod, err := ast.ParseModuleWithOpts(path, module, ast.ParserOptions{
36. 		ProcessAnnotation: true,
37. 		JSONOptions: &json.Options{
38. 			MarshalOptions: json.MarshalOptions{
39. 				IncludeLocation: json.NodeToggle{
40. 					AnnotationsRef: true,
41. 				},
42. 			},
43. 		},
44. 	})
45. 	if err != nil {
46. 		return nil, err
47. 	}
48. 
49. 	as, errs := ast.BuildAnnotationSet([]*ast.Module{mod})
50. 	if len(errs) > 0 {
51. 		return nil, errors.New(errs.Error())
52. 	}
53. 
54. 	results := make([]*ast.AnnotationsRef, 0, len(mod.Rules))
55. 	for _, rule := range mod.Rules {
56. 		results = append(results, as.Chain(rule)...)
57. 	}
58. 
59. 	return results, nil
60. }
61. 
62. func inspectMultiple(paths, modules []string) ([]*ast.AnnotationsRef, error) {
63. 	numPaths := len(paths)
64. 	numModules := len(modules)
65. 	if numPaths != numModules {
66. 		return nil, fmt.Errorf("mismatched number of paths and modules: %d != %d", numPaths, numModules)
67. 	}
68. 
69. 	results := make([]*ast.AnnotationsRef, 0, numPaths)
70. 	for i := 0; i < numPaths; i++ {
71. 		r, err := inspectSingle(paths[i], modules[i])
72. 		if err != nil {
73. 			return nil, err
74. 		}
75. 
76. 		results = append(results, r...)
77. 	}
78. 
79. 	return results, nil
80. }
81. 
82. // Borrowed from conftest
83. func isWarning(ruleName string) bool {
84. 	return regexp.MustCompile("^warn(_[a-zA-Z0-9]+)*$").MatchString(ruleName)
85. }
86. 
87. // Borrowed from conftest
88. func isFailure(ruleName string) bool {
89. 	return regexp.MustCompile("^(deny|violation)(_[a-zA-Z0-9]+)*$").MatchString(ruleName)
90. }
91. 
92. func isWarnOrDeny(rule *ast.AnnotationsRef) bool {
93. 	r := rule.GetRule()
94. 	if r == nil {
95. 		return false
96. 	}
97. 	ruleName := r.Head.Name.String()
98. 	return isWarning(ruleName) || isFailure(ruleName)
99. }
100. 
101. func hasAnnotations(rule *ast.AnnotationsRef) bool {
102. 	return rule.Annotations != nil
103. }
104. 
105. // Interesting rules are warns, denies, and anything with an annotation,
106. // which includes some package scoped annotations not assocated with a rule
107. func interestingRulesOnly(results []*ast.AnnotationsRef) ([]*ast.AnnotationsRef, error) {
108. 	filteredResults := make([]*ast.AnnotationsRef, 0, len(results))
109. 	for _, rule := range results {
110. 		if isWarnOrDeny(rule) || hasAnnotations(rule) {
111. 			filteredResults = append(filteredResults, rule)
112. 		}
113. 	}
114. 	return filteredResults, nil
115. }
