117. // destDir is usually something like /tmp/ec-workdir-1234/policy/f33dbeef so let's trim it
118. func shortPath(fullPath string, destDir string) string {
119. 	return strings.TrimPrefix(strings.TrimPrefix(fullPath, destDir), "/")
120. }
121. 
122. func checkRules(rules []*ast.AnnotationsRef) error {
123. 	for _, rule := range rules {
124. 		r := rule.GetRule()
125. 		if r == nil {
126. 			// not a rule
127. 			continue
128. 		}
129. 		head := r.Head
130. 		term := head.Value
131. 		var value ast.Value
132. 		if term != nil {
133. 			// cases when rule is assigned, e.g. deny = msg {...}
134. 			value = term.Value
135. 		} else {
136. 			// cases when rule is keyed, e.g. deny[msg] {...}
137. 			key := head.Key
138. 			value = key.Value
139. 		}
140. 
141. 		switch value.(type) {
142. 		case ast.String:
143. 			continue
144. 		case *ast.String:
145. 			continue
146. 		case ast.Object:
147. 			continue
148. 		case ast.Var:
149. 			continue
150. 		case ast.Call:
151. 			continue
152. 		}
153. 
154. 		return fmt.Errorf("the rule %q returns an unsupported value, at %s", r.String(), r.Location)
155. 	}
156. 
157. 	return nil
158. }
