160. // Finds all the rego files, inspects each one and returns a list the inspect data
161. func InspectDir(afs afero.Fs, dir string) ([]*ast.AnnotationsRef, error) {
162. 	regoPaths := []string{}
163. 	regoContents := []string{}
164. 
165. 	// Find all the rego files
166. 	// IMPORTANT: Resist the temptation to use afero.WalkDir here. If dir is a symlink, afero.Walk
167. 	// will not follow it. This is the case if dir was created by go-getter from a local file path.
168. 	// See afero issue https://github.com/spf13/afero/issues/284.
169. 	err := fs.WalkDir(wrapperFs{afs: afs}, dir, func(path string, d fs.DirEntry, readErr error) error {
170. 		if readErr != nil {
171. 			return readErr
172. 		}
173. 
174. 		if d.IsDir() {
175. 			return nil
176. 		}
177. 
178. 		pathLower := strings.ToLower(path)
179. 
180. 		if filepath.Ext(pathLower) != ".rego" {
181. 			return nil
182. 		}
183. 
184. 		// Prune out the tests early on
185. 		if strings.HasSuffix(filepath.Base(pathLower), "_test.rego") {
186. 			return nil
187. 		}
188. 
189. 		contents, err := afero.ReadFile(afs, path)
190. 		if err != nil {
191. 			return nil
192. 		}
193. 
194. 		regoPaths = append(regoPaths, shortPath(path, dir))
195. 		regoContents = append(regoContents, string(contents))
196. 		return nil
197. 	})
198. 	if err != nil {
199. 		return nil, err
200. 	}
201. 
202. 	// Ensure that we have actual rules, and a directory without rego files.
203. 	if len(regoPaths) == 0 {
204. 		log.Debug("No rego files found after cloning policy url.")
205. 		return nil, errors.New("no rego files found in policy subdirectory")
206. 	}
207. 
208. 	// Inspect all rego files found
209. 	allAnnotations, err := inspectMultiple(regoPaths, regoContents)
210. 	if err != nil {
211. 		return nil, err
212. 	}
213. 
214. 	// Return only interesting rules
215. 	result, err := interestingRulesOnly(allAnnotations)
216. 	if err != nil {
217. 		return nil, err
218. 	}
219. 
220. 	// check for conformance
221. 	if err := checkRules(result); err != nil {
222. 		return nil, err
223. 	}
224. 
225. 	return result, nil
226. }
