235. // to do this in order to change the first return type from afero.File to fs.File. Yes,
236. // even though afero.File conforms to the fs.File interface, go is not smart enough to
237. // detect this indirection.
238. func (w wrapperFs) Open(name string) (fs.File, error) {
239. 	return w.afs.Open(name)
240. }
