26. 
27. func title(a *ast.AnnotationsRef) string {
28. 	if a == nil || a.Annotations == nil {
29. 		return ""
30. 	}
31. 
32. 	return a.Annotations.Title
33. }
34. 
35. // xrefRegExp is used to detect asciidoc links in a string.
36. var xrefRegExp = regexp.MustCompile(`xref:[\w\.\$\#]+\[([\w\s/\.]+)\]`)
37. 
38. func description(a *ast.AnnotationsRef) string {
39. 	if a == nil || a.Annotations == nil {
40. 		return ""
41. 	}
42. 
43. 	// Unlink asciidoc text to avoid unexpected output
44. 	return xrefRegExp.ReplaceAllString(a.Annotations.Description, "$1")
45. }
46. 
47. func customAnnotationString(a *ast.AnnotationsRef, fieldName string) string {
48. 	if a == nil || a.Annotations == nil || a.Annotations.Custom == nil {
49. 		return ""
50. 	}
51. 	if value, ok := a.Annotations.Custom[fieldName].(string); ok {
52. 		return value
53. 	}
54. 	return ""
55. }
56. 
57. func effectiveOn(a *ast.AnnotationsRef) string {
58. 	return customAnnotationString(a, "effective_on")
59. }
60. 
61. func solution(a *ast.AnnotationsRef) string {
62. 	return xrefRegExp.ReplaceAllString(customAnnotationString(a, "solution"), "$1")
63. }
